1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
10	import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * First step of {@code POST /api/owners}. Rejects a request that is missing or blank in any
15	 * required owner field before {@link BuildOwner} runs, throwing {@link MissingFieldsException}
16	 * (handled as a 400 listing the offending field names). Normalizes the address (see
17	 * {@link OwnerAddress}) before that check, so an address left blank once whitespace is collapsed is
18	 * rejected as missing. Normalizes the telephone to E.164 form (see {@link OwnerTelephone}), throwing
19	 * {@link InvalidTelephoneException} (400) when it cannot form a valid number. Publishes the
20	 * normalized body for later steps, so the stored, returned and compared address is the normalized
21	 * form.
22	 */
23	public class RequireOwnerFields {
24	
25	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
26	            throws MissingFieldsException, InvalidTelephoneException, InvalidEmailException {
27	        request.setAddress(OwnerAddress.normalize(request.getAddress()));
28	        List<String> missing = new ArrayList<>();
29	        if (isBlank(request.getFirstName())) {
30	            missing.add("firstName");
31	        }
32	        if (isBlank(request.getLastName())) {
33	            missing.add("lastName");
34	        }
35	        if (isBlank(request.getAddress())) {
36	            missing.add("address");
37	        }
38	        if (isBlank(request.getCity())) {
39	            missing.add("city");
40	        }
41	        if (isBlank(request.getTelephone())) {
42	            missing.add("telephone");
43	        }
44	        if (!missing.isEmpty()) {
45	            throw new MissingFieldsException(missing);
46	        }
47	        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
48	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
49	        validated.set(request);
50	    }
51	
52	    private static boolean isBlank(String value) {
53	        return value == null || value.isBlank();
54	    }
55	}
