1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Step of {@code POST /api/owners} that records the owner's {@code namesakeCount}: the number of
9	 * existing owners (before this create) sharing the same first name and last name, compared
10	 * case-insensitively. Runs before {@link SaveOwner} so the owner being created is not itself
11	 * counted.
12	 */
13	public class CountNamesakes {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String firstName = owner.getFirstName();
17	        String lastName = owner.getLastName();
18	        int count = 0;
19	        for (Owner existing : ownerRepository.findAll()) {
20	            if (firstName.equalsIgnoreCase(existing.getFirstName())
21	                    && lastName.equalsIgnoreCase(existing.getLastName())) {
22	                count++;
23	            }
24	        }
25	        owner.setNamesakeCount(count);
26	    }
27	}
