1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * The single derived identity of a pet owner, consolidating the former telephone, email and
9	 * household duplicate checks into one derived key. The {@code identityKey} is
10	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone is
11	 * canonical E.164 form, the email is trimmed and lower-cased (or empty when absent) and the household
12	 * id is {@link Household#id(String, String)} over the last name and address.
13	 *
14	 * <p>Because the telephone is part of the key, two members of the same household (same householdId)
15	 * with different telephones have different identity keys and are both allowed; only owners that are
16	 * the same contact collide. Duplicate detection compares the {@link #contactKey(String, String)} —
17	 * the telephone-and-email prefix of the key that is what actually identifies one owner, so two owners
18	 * in the same household with different telephones (or emails) are distinct and both persist.
19	 *
20	 * <p>Used by {@link RequireUniqueIdentity} to reject a collision and by the owner mapper to expose
21	 * the full key on responses.
22	 */
23	public final class OwnerIdentity {
24	
25	    private OwnerIdentity() {
26	    }
27	
28	    /** The full identity key for an owner with the given raw fields, as exposed on responses. Fields
29	     *  are normalized here so the same value is produced whether they come from a freshly-validated
30	     *  request or a stored owner. */
31	    public static String key(String telephone, String email, String lastName, String address) {
32	        return contactKey(telephone, email) + "|" + Household.id(lastName, address);
33	    }
34	
35	    /** The telephone-and-email prefix of the identity key, identifying a single contact. Two owners
36	     *  are duplicates when their contact keys are equal. */
37	    public static String contactKey(String telephone, String email) {
38	        return normalizedTelephone(telephone) + "|" + normalizeEmail(email);
39	    }
40	
41	    /** The telephone in canonical E.164 form, or the raw value (or empty when {@code null}) when it
42	     *  cannot be normalized. Shared so the customer-code hash and the identity key normalize the
43	     *  telephone the same way. */
44	    public static String normalizedTelephone(String telephone) {
45	        try {
46	            return OwnerTelephone.toE164(telephone);
47	        }
48	        catch (InvalidTelephoneException ex) {
49	            return telephone == null ? "" : telephone;
50	        }
51	    }
52	
53	    private static String normalizeEmail(String email) {
54	        if (email == null || email.isBlank()) {
55	            return "";
56	        }
57	        return email.trim().toLowerCase(Locale.ROOT);
58	    }
59	}
