1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	/**
4	 * Thrown by the create-owner pipeline when the supplied owner's whole derived identity key
5	 * (normalized telephone, email and household id) equals an existing owner's. Handled globally by
6	 * {@link DuplicateIdentityExceptionHandler}, which responds 409 Conflict.
7	 */
8	public class DuplicateIdentityException extends Exception {
9	
10	    public DuplicateIdentityException(String message) {
11	        super(message);
12	    }
13	}
