1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
12	 * canonical region derived from the owner's postcode (falling back to its city; see
13	 * {@link Locality}) and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of
14	 * {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). The telephone is normalized to
15	 * E.164 form (see {@link OwnerIdentity#normalizedTelephone(String)}), the same normalization used by
16	 * the identity key. The code carries no per-city sequence, so it is derived purely from the owner's
17	 * own fields and is seed-independent.
18	 */
19	public class AssignCustomerCode {
20	
21	    public void service(@Val Owner owner) {
22	        String region = Locality.of(owner.getPostcode(), owner.getCity());
23	        String hash8 = hash8(OwnerIdentity.normalizedTelephone(owner.getTelephone()), owner.getLastName());
24	        owner.setCustomerCode(region + "-" + hash8);
25	    }
26	
27	    /** First 8 upper-case hex characters of SHA-256 over {@code (normalizedTelephone + lastName)}. */
28	    private static String hash8(String normalizedTelephone, String lastName) {
29	        String input = normalizedTelephone + (lastName == null ? "" : lastName);
30	        try {
31	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(input.getBytes(StandardCharsets.UTF_8));
32	            StringBuilder sb = new StringBuilder(8);
33	            // Two hex characters per byte, so four bytes yield the eight characters required.
34	            for (int i = 0; i < 4; i++) {
35	                sb.append(String.format("%02X", digest[i]));
36	            }
37	            return sb.toString();
38	        }
39	        catch (NoSuchAlgorithmException e) {
40	            throw new IllegalStateException("SHA-256 not available", e);
41	        }
42	    }
43	}
