3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Household identity for pet owners. Two owners belong to the same household when they share a last
9	 * name and address, compared case-insensitively with collapsed whitespace. The
10	 * {@link #id(String, String)} value is a stable identifier derived purely from those two fields, so
11	 * every owner in a household returns the same {@code householdId} without any stored state. Used as
12	 * one component of the owner {@link OwnerIdentity} key and by the owner mapper to expose the
13	 * identifier on responses.
14	 */
15	public final class Household {
16	
17	    private Household() {
18	    }
19	
20	    /** Trim, collapse internal whitespace and lower-case for case-insensitive comparison. */
21	    public static String normalize(String value) {
22	        if (value == null) {
23	            return "";
24	        }
25	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
26	    }
27	
28	    /**
29	     * A stable shared identifier for the household of an owner with the given last name and address.
30	     * Derived from the normalized fields, so owners in the same household get the same value.
31	     */
32	    public static String id(String lastName, String address) {
33	        String key = normalize(lastName) + "|" + normalize(address);
34	        try {
35	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
36	            StringBuilder sb = new StringBuilder(16);
37	            for (int i = 0; i < 8; i++) {
38	                sb.append(String.format("%02X", digest[i]));
39	            }
40	            return sb.toString();
41	        }
42	        catch (NoSuchAlgorithmException e) {
43	            throw new IllegalStateException("SHA-256 not available", e);
44	        }
45	    }
46	}
